# ---------- certificates ----------
def pratt(p, memo):
    if p in memo: return
    if p == 2: memo[2] = None; return
    fs = sympy.factorint(p - 1)
    for f in fs: pratt(f, memo)
    a = 2
    while not (pow(a, p - 1, p) == 1 and all(pow(a, (p - 1) // f, p) != 1 for f in fs)): a += 1
    memo[p] = (a, sorted(fs.items()))

def verify_pratt(p, memo, seen=None):
    if p == 2: return True
    a, fs = memo[p]
    prod = 1
    for f, e in fs: prod *= f ** e
    if prod != p - 1 or pow(a, p - 1, p) != 1: return False
    if any(pow(a, (p - 1) // f, p) == 1 for f, e in fs): return False
    return all(verify_pratt(f, memo) for f, e in fs)

class Fail(Exception): pass
def inv(x, N):
    x %= N
    if gcd(x, N) != 1: raise Fail('non-invertible')
    return pow(x, -1, N)
def ec_add(P, Q, a, N):
    if P is None: return Q
    if Q is None: return P
    x1, y1 = P; x2, y2 = Q
    if (x1 - x2) % N == 0:
        if (y1 + y2) % N == 0: return None
        if (y1 - y2) % N != 0: raise Fail('x equal, y inconsistent')
        lam = (3 * x1 * x1 + a) * inv(2 * y1, N) % N
    else:
        lam = (y2 - y1) * inv(x2 - x1, N) % N
    x3 = (lam * lam - x1 - x2) % N
    return (x3, (lam * (x1 - x3) - y1) % N)
def ec_mul(k, P, a, N):
    R = None
    for bit in bin(k)[2:]:
        R = ec_add(R, R, a, N)
        if bit == '1': R = ec_add(R, P, a, N)
    return R
def verify_ecpp(target, steps, memo):
    Nexp = target
    for (N, t, s, a4, x, y) in steps:
        if N != Nexp or gcd(N, 6) != 1: return False, 'N chain/gcd6'
        m = N + 1 - t
        if s <= 0 or m % s: return False, 's does not divide m'
        q = m // s
        b = (y * y - x ** 3 - a4 * x) % N
        if gcd((4 * a4 ** 3 + 27 * b * b) % N, N) != 1: return False, 'singular'
        try:
            Q = ec_mul(s, (x % N, y % N), a4, N)
            if Q is None: return False, '[s]P = O'
            if ec_mul(q, Q, a4, N) is not None: return False, '[m]P != O'
        except Fail as e:
            return False, str(e)
        c = icbrt(0)  # placeholder
        c = isqrt(isqrt(N))
        while c ** 4 < N: c += 1
        if not q > (c + 1) ** 2: return False, 'q too small'
        Nexp = q
    if Nexp >= 2 ** 64: return False, 'terminal not below 2^64'
    pratt(Nexp, memo)
    return verify_pratt(Nexp, memo), 'terminal Pratt'

def gp_primecert(Ns):
    prog = 'default(parisize,"1G");\n'
    for N in Ns:
        prog += f'N={N}; print("CERT ",N); c=primecert(N); for(i=1,#c,v=c[i]; print("STEP ",v[1]," ",v[2]," ",v[3]," ",v[4]," ",v[5][1]," ",v[5][2])); print("VALID ",primecertisvalid(c));\n'
    outp = subprocess.run(['gp', '-q', '-f'], input=prog, capture_output=True, text=True, check=True).stdout
    certs = {}; cur = None
    for line in outp.splitlines():
        parts = line.split()
        if not parts: continue
        if parts[0] == 'CERT': cur = int(parts[1]); certs[cur] = {'steps': [], 'pari_primecertisvalid': None}
        elif parts[0] == 'STEP': certs[cur]['steps'].append(tuple(int(z) for z in parts[1:7]))
        elif parts[0] == 'VALID': certs[cur]['pari_primecertisvalid'] = int(parts[1])
    return certs

M, P, I, PL = SR['C-PLANT-M'], SR['C-PLANT-P'], SR['C-INERT'], SR['C-PLANT-PL']
CF1 = 2 ** 255 - 19
CF2 = 2 ** 256 - 2 ** 224 + 2 ** 192 + 2 ** 96 - 1
required_prime = {
  'C-PLANT-M': {'d1': M['d1'], 'd2': M['d2'], 'u': M['u'], 'r': M['r'], 'v': M['v']},
  'C-PLANT-P': {'d': P['d'], 'w': P['w'], 'r': P['r'], 'q': P['q']},
  'C-INERT': {'w': I['w'], 'r': I['r'], 'q': I['q']},
  'C-PLANT-PL': {'f1': PL['f1'], 'f2': PL['f2'], 'f3': PL['f3'], 'f4': PL['f4'], 'w': PL['w'], 'r': PL['r'], 'q': PL['q']},
  'C-FIELD': {'CF-1': CF1, 'CF-2': CF2},
}
allp = sorted({v for dct in required_prime.values() for v in dct.values()} | {2, 3})
big = [p for p in allp if p >= 2 ** 64]
t = time.time(); certs = gp_primecert(big); cert_secs = time.time() - t
memo = {}
cert_report = {}
for p in allp:
    if p < 2 ** 64:
        pratt(p, memo)
        cert_report[str(p)] = {'kind': 'Pratt', 'witness_a': (memo[p][0] if memo[p] else None),
            'factors_of_p_minus_1': ([[f, e] for f, e in memo[p][1]] if memo[p] else []),
            'verified_by_own_verifier': verify_pratt(p, memo)}
    else:
        ok, why = verify_ecpp(p, certs[p]['steps'], memo)
        cert_report[str(p)] = {'kind': 'ECPP (PARI primecert) + terminal Pratt', 'steps': [[str(z) for z in st] for st in certs[p]['steps']],
            'terminal_q': str(certs[p]['steps'][-1][0] + 1 - certs[p]['steps'][-1][1]) if False else None,
            'pari_primecertisvalid': certs[p]['pari_primecertisvalid'], 'verified_by_own_verifier': ok, 'verifier_note': why}
pratt_leaves = {str(p): [memo[p][0], [[f, e] for f, e in memo[p][1]]] for p in memo if memo[p]}
# own-verifier tamper self-test: replace top N of 2^89-1 cert by 2^89+1
tc = gp_primecert([2 ** 89 - 1, 2 ** 127 - 1])
tamper_ok = verify_ecpp(2 ** 89 - 1, tc[2 ** 89 - 1]['steps'], memo)[0]
bad = list(tc[2 ** 89 - 1]['steps']); st = list(bad[0]); st[0] = 2 ** 89 + 1; bad[0] = tuple(st)
tamper_rej = not verify_ecpp(2 ** 89 + 1, bad, memo)[0]
selftest = {'2^89-1 accepted': tamper_ok, '2^127-1 accepted': verify_ecpp(2 ** 127 - 1, tc[2 ** 127 - 1]['steps'], memo)[0],
            'tampered (top N := 2^89+1) rejected': tamper_rej}

# ---------- classification ----------
DPS = 200
mp.dps = DPS
getcontext().prec = DPS + 10
TAU = mpf(10) ** -45
TIE = mpf(10) ** -100
def lg(x): return mpmath.log(x, 2)
def dlg(x): return Decimal(x).ln() / Decimal(2).ln()
def T(b, m, d):
    return mpmath.sqrt(mpf(m) / d) + (mpmath.sqrt(d) if b == 'minus' else mpf(d))
def dT(b, m, d):
    return (Decimal(m) / Decimal(d)).sqrt() + (Decimal(d).sqrt() if b == 'minus' else Decimal(d))
def e_of(b, r, m, d): return lg(T(b, m, d)) / lg(r)
def de_of(b, r, m, d): return dlg(dT(b, m, d)) / dlg(r)
def F(b, r):
    if b == 'minus': return (1 + lg(r - 1) / 4) / lg(r)
    return (lg(3) - mpf(2) / 3 + lg(r + 1) / 3) / lg(r)
def dF(b, r):
    if b == 'minus': return (1 + dlg(r - 1) / 4) / dlg(r)
    return (dlg(3) - Decimal(2) / 3 + dlg(r + 1) / 3) / dlg(r)
def Cc(b, r):
    m = r - 1 if b == 'minus' else r + 1
    return lg(mpmath.sqrt(m) + 1) / lg(r)
def dCc(b, r):
    m = r - 1 if b == 'minus' else r + 1
    return dlg(Decimal(m).sqrt() + 1) / dlg(r)
def bin_exact(s):
    flag = abs(s - mpf(1) / 4) <= TAU or abs(s - mpf(3) / 4) <= TAU
    if s >= mpf(3) / 4 + TAU: b = 'NEAR_FLOOR'
    elif s <= mpf(1) / 4 - TAU: b = 'NEAR_CEILING'
    elif abs(s - mpf(1) / 4) <= TAU: b = 'NEAR_CEILING'
    else: b = 'INTERMEDIATE'
    return b, flag
def bin_bound(s):
    b, flag = bin_exact(s)
    if s >= mpf(3) / 4 + TAU: return 'NEAR_FLOOR', None, flag
    return 'UNDETERMINED', b, flag
def divisors(fac):
    ds = [1]
    for p, e in fac.items():
        ds = [d * p ** k for d in ds for k in range(e + 1)]
    return sorted(set(ds))
def f6(x, n=12): return mpmath.nstr(x, n, strip_zeros=False)
INPUT_MODEL = {'minus': 'P, [x]P, [x^d]P (one auxiliary power, exponent d; Cheon 2006 Theorem 1)',
               'plus': '[x^i]P for i = 1..2d (2d consecutive auxiliary powers; Cheon 2006 Theorem 2)'}
def classify(r, b, cand, status='EXACT', fac=None):
    m = r - 1 if b == 'minus' else r + 1
    rows = []
    for d in cand:
        assert m % d == 0
        rows.append((d, e_of(b, r, m, d), de_of(b, r, m, d)))
    estar = min(x[1] for x in rows)
    ties = sorted(d for d, e, de in rows if e - estar <= TIE * estar)
    dmin = ties[0]
    e = e_of(b, r, m, dmin); de = de_of(b, r, m, dmin)
    Fb, Cb = F(b, r), Cc(b, r)
    s = (Cb - e) / (Cb - Fb)
    ds_ = (dCc(b, r) - de) / (dCc(b, r) - dF(b, r))
    if status == 'EXACT': bn, flag = bin_exact(s); bal = None
    else: bn, bal, flag = bin_bound(s)
    Tm = T(b, m, dmin)
    maxdiff = max(abs(mpf(str(x[2])) - x[1]) for x in rows)
    floor_ok = all(x[1] >= Fb - TAU for x in rows) if False else (e >= Fb - TAU)
    res = {'branch': b, 'status': status, 'm': str(m), 'm_bits': m.bit_length(),
           'factorization': ({str(p): k for p, k in fac.items()} if fac else None),
           'candidate_divisor_count': len(cand), 'e_star': f6(e, 40), 'minimiser': str(dmin), 'minimiser_bits': dmin.bit_length(),
           'tie_set': [str(d) for d in ties], 'tie_set_bits': [d.bit_length() for d in ties],
           'F_b': f6(Fb, 40), 'C_b': f6(Cb, 40), 'e_minus_F': mpmath.nstr(e - Fb, 25), 'depth_s': f6(s, 40),
           'bin' if status == 'EXACT' else 'bin': bn, 'bin_at_least': bal, 'boundary_flag': flag,
           'log2_T_at_minimiser': f6(lg(Tm), 30), 'log2_r': f6(lg(r), 30),
           'input_model': INPUT_MODEL[b], 'memory_elements_log2': f6(lg(max(mpmath.sqrt(mpf(m) / dmin), mpmath.sqrt(dmin))), 20),
           'log2_2d_plus_only': (f6(lg(2 * dmin), 20) if b == 'plus' else None),
           'floor_invariant_holds': bool(e >= Fb - TAU) and (b == 'minus' or all(T(b, m, d) >= d for d in cand)),
           'pathB_decimal_max_abs_diff_over_all_candidates': mpmath.nstr(maxdiff, 5),
           'pathB_decimal_depth_diff': mpmath.nstr(abs(mpf(str(ds_)) - s), 5),
           'divisor_table_sorted_by_e': [[str(d), d.bit_length(), f6(ee, 30)] for d, ee, _ in sorted(rows, key=lambda x: x[1])],
           '_e': e, '_F': Fb, '_s': s}
    if b == 'minus':
        lb = max(d for d in cand if d <= isqrt(r))
        res['secondary_bits_largest_divisor_le_isqrt_r'] = lb.bit_length()
    return res

fac = {
 'C-PLANT-M': {'minus': {2: 1, M['d1']: 1, M['d2']: 1, M['u']: 1}, 'plus': {2: 2, 3: 1, M['v']: 1}},
 'C-PLANT-P': {'minus': {2: 1, P['q']: 1}, 'plus': {2: 2, 3: 1, P['d']: 1, P['w']: 1}},
 'C-INERT': {'minus': {2: 1, I['q']: 1}, 'plus': {2: 2, 3: 1, I['w']: 1}},
 'C-PLANT-PL': {'minus': {2: 1, PL['q']: 1}, 'plus': {2: 2, 3: 1, PL['f1']: 1, PL['f2']: 1, PL['f3']: 1, PL['f4']: 1, PL['w']: 1}},
}
CL = {}
for cid, br in fac.items():
    r = SR[cid]['r']
    CL[cid] = {'r': str(r), 'r_bits': r.bit_length()}
    for b, fc in br.items():
        m = r - 1 if b == 'minus' else r + 1
        prod = 1
        for p, k in fc.items(): prod *= p ** k
        assert prod == m, (cid, b)
        CL[cid][b] = classify(r, b, divisors(fc), 'EXACT', fc)
        CL[cid][b]['product_check'] = prod == m
        CL[cid][b]['all_factors_certified'] = all(cert_report[str(p)]['verified_by_own_verifier'] for p in fc)

# ---------- C-BOUND ----------
def comp_witness(C):
    if C % 2 == 0: return '2 (even)'
    a = 2
    while strong_prp(C, a): a += 1
    return a
def is_perfect_power(n):
    for k in range(2, n.bit_length() + 1):
        x = sympy.integer_nthroot(n, k)
        if x[1]: return k
    return None
def witness_set(Fb, parts):
    out = set()
    for e in divisors(sympy.factorint(Fb)) if Fb > 1 else [1]:
        for k in range(len(parts) + 1):
            for S in itertools.combinations(parts, k):
                pr = 1
                for x in S: pr *= x
                out.add(e * pr)
    return sorted(out)
rM, rP = M['r'], P['r']
D, u, d, w = M['D'], M['u'], P['d'], P['w']
states = {
 'BND-1': (rM, 'minus', 2 * u, [D]),
 'BND-2': (rM, 'minus', 2, [M['d1'] * M['d2'] * u]),
 'BND-3': (rP, 'plus', 2, [2 * d, 3 * w]),
}
CB = {}
for sid, (r, b, Fb, parts) in states.items():
    m = r - 1 if b == 'minus' else r + 1
    pr = Fb
    for x in parts: pr *= x
    W = witness_set(Fb, parts)
    c = classify(r, b, W, 'BOUND')
    CB[sid] = {'row': 'C-PLANT-M' if r == rM else 'C-PLANT-P', 'branch': b, 'F': str(Fb), 'parts': [str(x) for x in parts],
      'parts_bits': [x.bit_length() for x in parts],
      'product_check': pr == m, 'parts_composite': [not sympy.isprime(x) for x in parts],
      'compositeness_witness': [comp_witness(x) for x in parts], 'perfect_power': [is_perfect_power(x) for x in parts],
      'W': [str(x) for x in W], 'W_bits': [x.bit_length() for x in W], 'status': 'BOUND', 'witness': c['minimiser'], 'witness_bits': c['minimiser_bits'],
      'tie_set': c['tie_set'],
      'upper_bound_exponent': c['e_star'], 'lower_bound_exponent_F': c['F_b'],
      'upper_bound_log2_T': c['log2_T_at_minimiser'], 'lower_bound_log2_equiv_F_times_log2r': f6(c['_F'] * lg(r), 30),
      'depth_s_of_witnessed_bound': c['depth_s'], 'bin': c['bin'], 'bin_at_least': c['bin_at_least'], 'boundary_flag': c['boundary_flag'],
      'floor_invariant_holds': c['floor_invariant_holds'], 'pathB_decimal_max_abs_diff': c['pathB_decimal_max_abs_diff_over_all_candidates'],
      'divisor_table_sorted_by_e': c['divisor_table_sorted_by_e'], '_e': c['_e']}
bnd1_consistency = abs(CB['BND-1']['_e'] - CL['C-PLANT-M']['minus']['_e'])

# ---------- text-claim checks ----------
mpc = {}
mM = rM - 1
mpc['BND-1: D within factor 1+2^-37 of sqrt(m)'] = mpmath.nstr(abs(mpf(D) / mpmath.sqrt(mM) - 1), 8) + ' vs 2^-37=' + mpmath.nstr(mpf(2) ** -37, 8)
mpc['BND-1: 2u within factor 1+2^-37 of sqrt(m)'] = mpmath.nstr(abs(mpf(2 * u) / mpmath.sqrt(mM) - 1), 8)
mpc['C-PLANT-M: D rel. distance to S=isqrt(M0)'] = mpmath.nstr(abs(mpf(D) / M['S'] - 1), 8)
mP = rP + 1
mpc['C-PLANT-P/BND-3: d rel. distance to (m/4)^(1/3)'] = mpmath.nstr(abs(mpf(d) / mpmath.cbrt(mpf(mP) / 4) - 1), 8) + ' vs 2^-60=' + mpmath.nstr(mpf(2) ** -60, 8)
mpc['C-PLANT-P declared_size_of_planted_divisor'] = {'d_bits': d.bit_length(), 'd0_bits': P['d0'].bit_length(), 'd>=d0': d >= P['d0']}
DL, xL = PL['DL'], PL['xL']
mpc['C-PLANT-PL (b): D_L in [x_L, x_L(1+2^-19))'] = {'D_L>=x_L': DL >= xL, 'rel': mpmath.nstr(mpf(DL) / xL - 1, 8), '2^-19': mpmath.nstr(mpf(2) ** -19, 8)}
mpc['C-PLANT-PL (b): rel diff (r+1)/4 vs M_L/4 (<2^-290)'] = mpmath.nstr(abs(mpf(PL['r'] + 1) / (3 * mpf(2) ** 519) - 1), 8) + ' ; 2^-290=' + mpmath.nstr(mpf(2) ** -290, 8)
mpc['C-PLANT-PL (b): D_L rel. to T_plus optimum ((r+1)/4)^(1/3) (<2^-18)'] = mpmath.nstr(abs(mpf(DL) / mpmath.cbrt(mpf(PL['r'] + 1) / 4) - 1), 8)
mpc['C-PLANT-PL (a): all of f1..f4, w > 2^24'] = all(x > 2 ** 24 for x in [PL['f1'], PL['f2'], PL['f3'], PL['f4'], PL['w']])
mpc['C-PLANT-PL (a): bits of (r+1)/12 (must exceed 272)'] = ((PL['r'] + 1) // 12).bit_length()
mpc['C-PLANT-PL G ~ 2^129 (log2 G)'] = mpmath.nstr(lg(PL['G']), 8)
mpc['C-PLANT-PL x_L ~ 2^172 (log2 x_L)'] = mpmath.nstr(lg(xL), 8)
mpc['C-PLANT-PL w > 2^300 (bits of w)'] = PL['w'].bit_length()
mpc['C-PLANT-PL window f4 in [y, y+2^24) and f4 > f3'] = (PL['y'] <= PL['f4'] < PL['y'] + 2 ** 24) and PL['f4'] > PL['f3']
mpc['M0/4 and M_L/4 integers'] = (3 * 2 ** 254) % 4 == 0 and (3 * 2 ** 519) % 4 == 0
mpc['bit lengths of r: M,P,I,PL'] = [rM.bit_length(), rP.bit_length(), I['r'].bit_length(), PL['r'].bit_length()]
mpc['distinct r across constructions'] = len({rM, rP, I['r'], PL['r']}) == 4
# BND-2 text inequality: depth < 1/100
mpc['BND-2 depth < 1/100'] = mpf(CB['BND-2']['depth_s_of_witnessed_bound'][:60]) < mpf(1) / 100

# ---------- C-FIELD (from the text; extraction is a Stage P input not readable here) ----------
def hasse(p, h, r):
    lhs = abs(p + 1 - h * r); rhs = 2 * isqrt(p) + 2
    return lhs, rhs, lhs <= rhs
cf = {}
for cid, val, h in [('CF-1', CF1, 8), ('CF-2', CF2, 1)]:
    lhs, rhs, ok = hasse(val, h, val)
    reasons = ['field_prime']            # by definition FP contains both C-FIELD expression values
    if not cert_report[str(val)]['verified_by_own_verifier']: reasons.append('not_prime')
    if not ok: reasons.append('hasse')
    mut = [x for x in reasons if x != 'field_prime']
    cf[cid] = {'value': str(val), 'bits': val.bit_length(), 'h_used_as_stated_in_text': h, 'prime_certified': cert_report[str(val)]['verified_by_own_verifier'],
               'hasse_lhs_bits': lhs.bit_length(), 'hasse_lhs': str(lhs), 'hasse_rhs': str(rhs), 'hasse_within_bound': ok,
               'reason_list': reasons, 'mutation_reason_list': mut}
# construction controls vs the two known members of FP (C-FIELD values)
ctrl_vs_cf = {cid: (SR[cid]['r'] in (CF1, CF2)) for cid in SR}

for dct in list(CL.values()):
    for b in ('minus', 'plus'):
        for k in ('_e', '_F', '_s'): dct[b].pop(k, None)
for dct in CB.values(): dct.pop('_e', None)
out = {'libraries': {'python': sys.version.split()[0], 'mpmath': mpmath.__version__, 'sympy': sympy.__version__,
        'pari_gp': subprocess.run(['gp', '-q', '-f'], input='print(version())', capture_output=True, text=True).stdout.strip(), 'mp.dps': DPS, 'decimal_prec': DPS + 10},
       'search': SR, 'certificates': cert_report, 'pratt_tree': pratt_leaves, 'verifier_selftest': selftest, 'cert_gen_seconds': cert_secs,
       'classification': CL, 'c_bound': CB, 'bnd1_consistency_abs_diff': mpmath.nstr(bnd1_consistency, 5),
       'text_claim_checks': mpc, 'c_field': cf, 'construction_r_equals_a_CFIELD_value': ctrl_vs_cf, 'total_seconds': time.time() - T0}
json.dump(out, sys.stdout, indent=1, default=str)
